from math import sqrt

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    largest_prime = -1
    while n % 2 == 0:
        largest_prime = 2
        n //= 2
    for i in range(3, int(sqrt(n)) + 1, 2):
        while n % i == 0:
            largest_prime = i
            n //= i
    if n > 2:
        largest_prime = n
    return largest_prime
```

